using WAID.Application.Services;using WAID.Infrastructure.Persistence;namespace WAID.Infrastructure.Tests;public sealed class PerformanceHistoryPersistenceTests
{[Fact]public async Task Samples_rollups_quality_and_retention_round_trip(){var path=Path.Combine(Path.GetTempPath(),$"waid-performance-{Guid.NewGuid():N}.db");try{var db=new WaidDatabase($"Data Source={path};Pooling=False");await db.InitializeAsync(CancellationToken.None);var repo=new SqlitePerformanceHistoryRepository(db);var now=DateTimeOffset.UtcNow;var samples=new[]{new PerformanceMetricSample(Guid.NewGuid(),PerformanceMetricKind.CpuUtilization,now.AddDays(-10),25,"percent",MetricQuality.Measured,"test"),new PerformanceMetricSample(Guid.NewGuid(),PerformanceMetricKind.CpuUtilization,now,35,"percent",MetricQuality.Measured,"test")};await repo.SaveSamplesAsync(samples,CancellationToken.None);var rollup=new PerformanceMetricRollup(Guid.NewGuid(),PerformanceMetricKind.CpuUtilization,MetricResolution.Daily,now.Date,now.Date.AddDays(1),35,35,35,35,1,100,"percent",MetricQuality.Measured,PerformanceAggregationEngine.Version);await repo.ReplaceRollupsAsync(PerformanceMetricKind.CpuUtilization,MetricResolution.Daily,now.AddDays(-30),[rollup],CancellationToken.None);var loaded=await repo.ReadRollupsAsync(new(PerformanceMetricKind.CpuUtilization,now.AddDays(-1),now.AddDays(2),MetricResolution.Daily),CancellationToken.None);Assert.Single(loaded);Assert.Equal(35,loaded[0].Average);var generation=repo.Generation;var job=await repo.ApplyRetentionAsync(now.AddDays(-5),now.AddYears(-1),CancellationToken.None);Assert.Equal(1,job.DeletedSamples);Assert.True(repo.Generation>generation);Assert.Single(await repo.ReadSamplesAsync(PerformanceMetricKind.CpuUtilization,now.AddDays(-30),now.AddDays(1),CancellationToken.None));}finally{Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();if(File.Exists(path))File.Delete(path);}}}
